b_standard_deduction = observation(entity='Alice', entity_source='s55', predicate='allowed a deduction under section 63(c)', predicate_source='s55')
b_personal_exemptions = observation(entity='Alice', entity_source='s55', predicate='deductions of $4000 under section 151', predicate_source='s55')
b_gross_income = observation(entity='Alice', entity_source='s55', predicate='paid $33200', predicate_source='s55')
b_taxable_income = observation(entity='Alice', entity_source='s56', predicate='taxable income in 2017 is equal to $31200', predicate_source='s56')
@scope('s0') 
def taxable_income_definition_scope(): 
    return True 
@scope('s1') 
def taxable_income_general_scope(): 
    return taxable_income_definition_scope 
@scope('s2') 
def taxable_income_deductions_scope(): 
    return taxable_income_general_scope 
@scope('s3') 
def taxable_income_non_itemize_scope(): 
    return taxable_income_general_scope 
@scope('s4') 
def taxable_income_non_itemize_details_scope(): 
    return taxable_income_non_itemize_scope 
@scope('s5') 
def standard_deduction_scope(): 
    return taxable_income_general_scope 
@scope('s6') 
def personal_exemptions_scope(): 
    return taxable_income_non_itemize_details_scope 
@rule('s2', otherwise=False) 
def taxable_income_definition(): 
    return (taxable_income_deductions_scope and (b_gross_income - b_standard_deduction - b_personal_exemptions)) 
@rule('s56', otherwise=False) 
def taxable_income_query(): 
    return (taxable_income_definition and b_taxable_income) 
query = ('Entailment' if taxable_income_query else 'Contradiction')
